import {STUDIO_CATEGORIES,studioChoices,studioComplete,showInfo} from './engine.js?v=0.10.4';
import {tileCard,tileDetails,esc} from './tile-ui.js?v=0.10.4';
import {icon} from './icons.js?v=0.10.4';
const labels={add:'Ajouter',upgrade:'Améliorer',remove:'Retirer'};
export function studioMarkup(game,p,{category='add',selection=null,locked=false}={}){
 const choices=studioChoices(p,category),adding=category==='add',selected=choices.find(t=>(adding?t.kind:t.id)===selection)||choices[0],done=p.studio?.[category],count=STUDIO_CATEGORIES.filter(k=>p.studio?.[k]).length,next=showInfo(game.show+1),departed=p.studio?.departed;
 return `<section class="studio-screen" aria-label="Le Studio"><div class="studio-decoration" aria-hidden="true"><i></i><i></i><i></i></div><header class="studio-hero"><img src="art/studio/decors/studio-panorama.png" alt="" width="2172" height="724"><div class="studio-heading"><small>ENTRE DEUX SHOWS</small><h1>LE STUDIO</h1></div><button class="action-button studio-bilan" data-action="studio-bilan">Bilan</button><p>Préparez le prochain show</p></header><div class="studio-progress" role="status"><strong>${count}/3 catégories complétées</strong><span>1 choix par catégorie</span></div><div class="studio-tabs" role="group" aria-label="Catégories du Studio">${STUDIO_CATEGORIES.map((k,i)=>`<button class="${category===k?'active':''} ${p.studio?.[k]?'complete':''}" data-action="reward-tab" data-kind="${k}" aria-pressed="${category===k}">${p.studio?.[k]?'✓ ':''}${labels[k]}${p.studio?.[k]?`<small>${p.studio[k].status==='skipped'?'Passée':'Complétée'}</small>`:''}</button>`).join('')}</div><section class="studio-choices"><h2>${labels[category]} une tuile</h2>${done?`<p class="studio-done">✓ ${done.status==='skipped'?'Catégorie passée, sans effet.':'Catégorie complétée.'}</p>`:`${choices.length?`<div class="studio-gallery" role="group" aria-label="Tuiles du Studio">${choices.map(t=>tileCard(t,{action:'select-reward',attributes:`data-id="${esc(adding?t.kind:t.id)}" aria-pressed="${t===selected}"`,classes:t===selected?'chosen':''})).join('')}</div><div class="studio-detail">${tileDetails(selected,{upgrade:category==='upgrade'})}</div>`:`<p class="studio-empty">${category==='upgrade'?'Aucune tuile ne peut être améliorée.':category==='remove'?'Ton inventaire est vide : aucune tuile à retirer.':'Aucune proposition disponible.'} Tu peux passer cette catégorie.</p>`}<div class="studio-confirm">${selected?`<button class="action-button primary" data-action="choose-${category}" ${adding?`data-kind="${selected.kind}"`:`data-id="${esc(selected.id)}"`} ${locked?'disabled':''}>${{add:'CONFIRMER L’AJOUT',upgrade:'CONFIRMER L’AMÉLIORATION',remove:'CONFIRMER LE RETRAIT'}[category]} ${icon('arrow')}</button>`:''}<button class="action-button text-button" data-action="skip-reward" ${locked?'disabled':''}>Passer cette catégorie</button></div>`}</section><footer class="studio-next"><img src="art/studio/stickers/billet-prochain-show.png" alt=""><div><strong>PROCHAIN SHOW · ${esc(next.name)}</strong><span>${departed?'En attente du partenaire…':count===3?'Tout est prêt.':`Encore ${3-count} catégorie${count<2?'s':''} à compléter.`}</span></div><button class="action-button primary" data-action="studio-depart" ${!studioComplete(p)||departed||locked?'disabled':''}>${departed?'EN ATTENTE…':'PARTIR EN SHOW'} ${icon('arrow')}</button></footer></section>`;
}
export function studioConfirmation(root,reduced){if(reduced)return;const badge=root.querySelector('.studio-progress');badge?.animate([{transform:'scale(1.04)',background:'#ffa5d4'},{transform:'scale(1)',background:'#e5dfc8'}],{duration:250});const el=document.createElement('i');el.className='studio-burst';el.setAttribute('aria-hidden','true');root.querySelector('.studio-screen')?.append(el);el.animate([{opacity:0,transform:'scale(.6)'},{opacity:1,transform:'scale(1)',offset:.3},{opacity:0,transform:'scale(1.1)'}],{duration:350}).finished.catch(()=>{}).then(()=>el.remove());}
